'use strict';
// Three columns: journal, board and insurance. Economy lives in a small modal.
const leftSidebar=document.createElement('aside');leftSidebar.className='left-sidebar';leftSidebar.setAttribute('aria-label','總體經濟');
leftSidebar.innerHTML='<div class="sidebar-title"><div><span class="eyebrow">🌤 世界近況</span><h2>總體經濟</h2></div><button id="close-left" class="close-panel">關閉 ✕</button></div><div class="left-content"><section id="left-macro"><div id="macro-content"></div></section></div>';
const rightSidebar=document.createElement('aside');rightSidebar.className='right-sidebar';rightSidebar.setAttribute('aria-label','遊戲紀錄');
rightSidebar.innerHTML='<div class="sidebar-title"><div><span class="eyebrow">📖 冒險手帳</span><h2>遊戲紀錄</h2></div><button id="close-right" class="close-panel">關閉 ✕</button></div><p class="journal-intro">每一步，都是你的人生故事。</p><div class="journal-content"></div>';
const workspace=document.querySelector('.workspace');workspace.prepend(rightSidebar);workspace.append(pack);pack.classList.add('docked-insurance');rightSidebar.classList.add('journal-sidebar');rightSidebar.querySelector('.journal-content').append($('history'));
const macroDialog=document.createElement('dialog');macroDialog.id='macro-dialog';macroDialog.setAttribute('aria-label','總體經濟');macroDialog.append(leftSidebar);document.body.append(macroDialog);
document.querySelector('.history-head').hidden=true;
document.querySelector('[data-tab=insurance]').click();
document.querySelector('.planning .eyebrow').textContent='🛡 安心小屋';document.querySelector('.planning h2').textContent='保險與生活規劃';
document.querySelector('.event-panel').hidden=true;
const historyTitle=document.createElement('div');historyTitle.className='board-note';historyTitle.textContent='擲骰前可規劃 · 事件發生時自動暫停';document.querySelector('.play-panel').append(historyTitle);
const macroSummary=document.createElement('div');macroSummary.id='board-macro';document.querySelector('.board-center').prepend(macroSummary);
const policyHost=document.createElement('section');policyHost.id='investment-policy';$('policies').before(policyHost);
$('open-pack').querySelector('.tool-label').textContent='保險規劃';$('open-pack').querySelector('.tool-icon').textContent='🛡';
$('open-log').querySelector('.tool-label').textContent='總體經濟';$('open-log').querySelector('.tool-icon').textContent='🌤';
const extraLog=document.createElement('button');extraLog.id='open-right-log';extraLog.innerHTML='<span class="tool-icon">📖</span><span class="tool-label">遊戲紀錄</span>';document.querySelector('.game-toolbar').insertBefore(extraLog,$('game-report'));
function closeSidebars(){rightSidebar.classList.remove('mobile-open');if(macroDialog.open)macroDialog.close();$('open-log').setAttribute('aria-expanded','false');$('open-right-log').setAttribute('aria-expanded','false');}
function openSidebar(side){pause();togglePack(false);closeSidebars();if(side===leftSidebar){macroDialog.showModal();$('open-log').setAttribute('aria-expanded','true');}else{rightSidebar.classList.add('mobile-open');$('open-right-log').setAttribute('aria-expanded','true');}}
$('open-log').onclick=()=>openSidebar(leftSidebar);$('open-right-log').onclick=()=>openSidebar(rightSidebar);$('close-left').onclick=closeSidebars;$('close-right').onclick=closeSidebars;
const gameMenu=document.createElement('nav');gameMenu.className='game-menu';gameMenu.setAttribute('aria-label','遊戲工具');
gameMenu.append($('open-log'),$('game-report'),$('fullscreen'),$('open-right-log'),$('open-pack'));
document.querySelector('.play-panel>.section-top').append(gameMenu);toolbar.remove();
$('open-log').querySelector('.tool-label').textContent='總經';$('game-report').querySelector('.tool-label').textContent='回顧';$('open-right-log').querySelector('.tool-label').textContent='紀錄';$('open-pack').querySelector('.tool-label').textContent='保險';
macroDialog.addEventListener('close',()=>$('open-log').setAttribute('aria-expanded','false'));
const priorPack=$('open-pack').onclick;$('open-pack').onclick=()=>{closeSidebars();priorPack();};
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSidebars();});
document.addEventListener('focusin',e=>{if(e.target.matches('input,select'))pause();});
function rate(n){return (n*100).toFixed(1)+'%';}
function renderMacro(){if(!state)return;const m=E.MARKETS[state.market];$('macro-content').innerHTML=`<div class="macro-heading"><span>當前情境</span><strong>${m.name}</strong><small>${state.marketPeriods?`還有 ${state.marketPeriods/2} 年`:'持續至下一次市場事件'}</small></div><div class="macro-grid"><div><small>通膨年率</small><strong>${rate(m.inflation)}</strong></div><div><small>模擬政策利率</small><strong>${rate(m.rate)}</strong></div><div><small>你的貸款年利率</small><strong>${state.interest.toFixed(1)}%</strong></div><div><small>現金年利率</small><strong>${rate(m.deposit)}</strong></div><div><small>情境 GDP 成長率</small><strong>${rate(m.gdp)}</strong></div><div><small>情境失業率</small><strong>${rate(m.jobless)}</strong></div></div><div class="scenario-return"><h3>本情境的模擬年報酬中心</h3><div><span>股票</span><strong>${rate(m.stock)}</strong></div><div><span>債券</span><strong>${rate(m.bond)}</strong></div><p class="hint">實際半年報酬另加波動，這些數字不保證獲利。GDP與失業率是情境指標；事件抽樣使用該情境的失業風險倍數。</p></div><div class="insight"><span>哪些數字會改變生活？</span><p>通膨推升生活費；政策利率連動浮動貸款利率；現金產生利息。股債報酬也同步影響投資型保單。情境結束後回到平穩參數。</p></div><div class="asset-row"><span>累計物價變化</span><strong>+${((state.priceIndex-1)*100).toFixed(1)}%</strong></div><div class="asset-row"><span>累計現金利息</span><strong>${money(state.totalDepositInterest)}</strong></div><p class="hint">所有參數為虛構教學情境，非即時經濟資料。</p>`;
  $('board-macro').textContent=`通膨 ${rate(m.inflation)} · 貸款 ${state.interest.toFixed(1)}%`;
}
function policyTerms(){return '<details class="policy-terms"><summary>查看教學費率與計算規則</summary><p>保費費用：每筆3%。每月管理費100元；帳戶費年率0.8%、基金費年率0.6%，均按月從帳戶扣除。保障成本依年齡與淨危險保額計算，慢性病情境乘1.7。帳戶與保額100萬元取較大者作為身故給付。</p><p>解約／部分提領費率：第1–5保單年依序6%、5%、4%、3%、2%；第6年起0%。部分提領後至少保留1萬元。每保單年12次免費轉換，第13次起每次500元。</p><p>每半年模擬6次月扣費。續繳現金不足時跳過，帳戶仍繼續扣費；扣到零即失效。普通現金、債券、股票用盡後，系統最後強制解約補支出，費用照扣。未模擬核保、稅務、外幣、保單借款或催告寬限期。</p><p>這是獨立教學契約，以上數值不是法巴費率。費用類型參考<a href="https://life.cardif.com.tw/zh/p85" target="_blank" rel="noopener">法巴公開投資型商品說明 ↗</a>。</p></details>';}
function renderInvestment(){if(!state)return;const p=state.investmentPolicy,q=E.investmentSnapshot(state),disabled=state.ended?'disabled':'';
  if(q){policyHost.innerHTML=`<article class="investment-card"><div class="eyebrow">INVESTMENT-LINKED · 教學契約</div><h3>投資型壽險 <span>● 生效中</span></h3><div class="policy-value">${money(q.value)}<small>帳戶價值 NT$</small></div><div class="policy-facts"><div><span>保單年度</span><strong>第 ${q.year} 年</strong></div><div><span>現在全解約實領</span><strong>${money(q.net)}</strong></div><div><span>解約費用</span><strong class="negative">${money(q.fee)}（${rate(q.rate)}）</strong></div><div><span>身故給付</span><strong>${money(q.deathBenefit)}</strong></div><div><span>本月估算保障成本</span><strong>${money(q.monthlyRisk)}</strong></div><div><span>累計投入／費用</span><strong>${money(p.paid)}／${money(p.fees)}</strong></div></div><form id="policy-config-form"><div class="two-fields"><label>年度續繳（可填0）<input name="annualPremium" type="number" min="0" max="1000000000" step="1" value="${p.annualPremium}" required></label><label>股票比例 %<input name="stockWeight" type="number" min="0" max="100" step="1" value="${Math.round(p.stockWeight*100)}" required></label></div><p class="hint">其餘投入債券；本保單年已轉換 ${p.switchYear===q.year?p.switches:0} 次。前12次免費。</p><button class="secondary full" ${disabled}>更新續繳與配置</button></form><form id="policy-topup-form"><label>追加保費<input name="amount" type="number" min="1000" max="1000000000" step="1" value="10000" required></label><button class="secondary full" ${disabled}>預覽追加保費</button></form><form id="policy-withdraw-form"><label>部分提領：扣除的帳戶金額<input name="amount" type="number" min="1000" max="${p.value}" step="1" value="10000" required></label><button class="secondary full" ${disabled}>預覽部分提領</button></form><button class="danger full" id="policy-surrender" ${disabled}>預覽全部解約</button>${policyTerms()}</article>`;
  }else{const status=p?{lapsed:'帳戶耗盡，前份保單已失效。',paid:'前份保單已完成身故給付。',surrendered:'前份保單已解約，保障停止。'}[p.status]||'':'';policyHost.innerHTML=`<article class="investment-card"><div class="eyebrow">INVESTMENT-LINKED · 教學契約</div><h3>投資型壽險</h3><p class="hint">${status}保費扣費後投入股債；帳戶會波動，提前解約可能同時承受虧損與費用。</p><form id="policy-open-form"><label>首筆保費（至少1萬元）<input name="amount" type="number" min="10000" max="1000000000" step="1" value="100000" required></label><div class="two-fields"><label>年度續繳（可填0）<input name="annualPremium" type="number" min="0" max="1000000000" step="1" value="60000" required></label><label>股票比例 %<input name="stockWeight" type="number" min="0" max="100" step="1" value="60" required></label></div><button class="primary full" ${disabled}>預覽投保與費用</button></form>${policyTerms()}</article>`;}
  const budgetRow=document.createElement('div');budgetRow.className='asset-row';budgetRow.innerHTML=`<span>投資型預定年續繳</span><strong>${money(q?.annualPremium||0)}</strong>`;$('budget-summary').append(budgetRow);
}
const priorRender=render;render=function(){if(state)E.upgrade(state);priorRender();renderMacro();renderInvestment();};
const priorReport=openReport;openReport=function(){priorReport();if(!state)return;const p=state.investmentPolicy,q=E.investmentSnapshot(state);const div=document.createElement('div');div.className='report-copy';div.innerHTML=`<h3>投資型保單與費用</h3><p>累計投入 ${money(state.totalInvestmentPremium)} 元，帳戶投資損益 ${money(state.totalPolicyReturn)} 元，各項費用 ${money(state.totalPolicyFees)} 元（含解約／提領費 ${money(state.totalSurrenderFees)} 元）。目前帳戶 ${money(q?.value||0)} 元，強制解約領回 ${money(state.forcedPolicyCash)} 元。</p><p>身故時投資型給付 ${money(state.investmentDeathBenefit)} 元，已納入家屬總給付，帳戶不再重複計入資產。保單${p?'狀態：'+({active:'生效',lapsed:'失效',paid:'已給付',surrendered:'已解約'}[p.status]||p.status):'尚未投保'}。</p><p class="hint">風險保障保費與投資型投入分開列示；投入帳戶的本金不是全數費用。</p>`;$('report-content').append(div);};$('report').onclick=openReport;
const transactionDialog=document.createElement('dialog');transactionDialog.id='transaction-dialog';transactionDialog.setAttribute('aria-label','確認保單操作');transactionDialog.innerHTML='<div class="report-top"><span class="eyebrow">POLICY TRANSACTION</span><button id="cancel-transaction" class="text-btn">取消 ✕</button></div><div id="transaction-content"></div><p id="transaction-error" role="alert" class="negative"></p><button id="confirm-transaction" class="primary full">確認執行</button>';document.body.append(transactionDialog);let pendingTransaction=null;
function preview(title,body,fn){pause();pendingTransaction=fn;$('transaction-error').textContent='';$('transaction-content').innerHTML=`<h2>${title}</h2><div class="report-copy">${body}</div><p class="hint">確認後立即生效，尚未確認前不會扣款。</p>`;transactionDialog.showModal();}
$('cancel-transaction').onclick=()=>transactionDialog.close();transactionDialog.addEventListener('close',()=>pendingTransaction=null);
$('confirm-transaction').onclick=()=>{if(!pendingTransaction)return;const result=pendingTransaction();if(result){$('transaction-error').textContent=result;message(result,true);return;}transactionDialog.close();message('保單操作已完成，金額與費用已記入右側紀錄。');render();};
policyHost.addEventListener('submit',e=>{e.preventDefault();pause();const data=Object.fromEntries(new FormData(e.target));Object.keys(data).forEach(k=>data[k]=Number(data[k]));
  if(e.target.id==='policy-open-form'){const fee=Math.round(data.amount*E.INVESTMENT_TERMS.entry);preview('確認投保投資型壽險',`<p>現金扣款：${money(data.amount)} 元</p><p>保費費用：${money(fee)} 元（3%）</p><p>實際入帳：${money(data.amount-fee)} 元</p><p>年度續繳 ${money(data.annualPremium)} 元，股票 ${data.stockWeight}%／債券 ${100-data.stockWeight}%。帳戶仍負擔月扣費及波動，提前解約另收費。</p>`,()=>E.openInvestment(state,{...data,stockWeight:data.stockWeight/100}));}
  if(e.target.id==='policy-topup-form'){const fee=Math.round(data.amount*.03);preview('確認追加保費',`<p>現金扣款 ${money(data.amount)} 元，費用 ${money(fee)} 元，帳戶增加 ${money(data.amount-fee)} 元。</p>`,()=>E.topUpInvestment(state,data.amount));}
  if(e.target.id==='policy-config-form'){const p=state.investmentPolicy,y=E.investmentYear(state),count=p.switchYear===y?p.switches:0,fee=p.stockWeight!==data.stockWeight/100&&count>=12?500:0;preview('確認配置與續繳',`<p>年度續繳 ${money(data.annualPremium)} 元；股票 ${data.stockWeight}%、債券 ${100-data.stockWeight}%。</p><p>本次轉換費 ${fee} 元。已扣費用不會退還。</p>`,()=>E.configureInvestment(state,{...data,stockWeight:data.stockWeight/100}));}
  if(e.target.id==='policy-withdraw-form')withdrawPreview(data.amount,false);
});
function withdrawPreview(amount,all){const q=E.quoteInvestment(state,amount,all);if(q.error){message(q.error,true);return;}preview(all?'確認全部解約':'確認部分提領',`<p>帳戶扣除：${money(q.gross)} 元</p><p>第 ${E.investmentYear(state)} 保單年，費率 ${rate(q.rate)}</p><p>扣除費用：${money(q.fee)} 元</p><p><strong>現金實領：${money(q.net)} 元</strong></p><p>剩餘帳戶 ${money(q.remaining)} 元。${all?'保障與後續續繳會停止。':'未提領部分繼續承擔市場波動與扣費。'}</p>`,()=>E.redeemInvestment(state,amount,all));}
policyHost.addEventListener('click',e=>{if(e.target.closest('#policy-surrender'))withdrawPreview(0,true);});
const priorShowEvent=showEvent;showEvent=function(e){priorShowEvent(e);pause();state.pendingEvent=true;save();syncEventDetails();if(!eventDialog.open)eventDialog.showModal();};
eventDialog.addEventListener('close',()=>{if(state){state.pendingEvent=false;save();if(state.ended)openReport();}});
document.querySelector('.event-details').textContent='重看上一張事件';
document.querySelectorAll('.tile').forEach((tile,i)=>{tile.children[2].textContent=E.LABELS[E.CATEGORIES[i%4]];});
if(state){render();if(state.pendingEvent){syncEventDetails();eventDialog.showModal();}}
